- #1 Ar Rahmaan     ሙእሚንም ካሐዲም ለሆኑ ፍጡራን እዝነቱ ሰፊና ትልቅ 1:3; 17:110
- #2 Ar Raheem      ከስራ እጥፍ ድርብ የላቀ ምንዳ የሚሰጥ (ለሙእሚኖች በተለየ ሁኔታ) 2:163; 3:31; 4:100; 5:3
- #3 Al Malik       በግዛቱ ያሻውን የሚፈጽም ንጉስ 20:114; 23:116; 59:23; 62:1
- #4 Al Quddus      በስሜት ሕዋሳት ሊደረስበት ወይም በምናብ ሊታሰብ ከሚችል ባህሪ ሁሉ የጸዳ 59:23; 62:1
- #5 As Salaam      ከነውር እና ከጉድለት የጸዳ፤ ሰላሙን በፍጡራኑ ላይ የሚያሰፍን 59:23
- #6 Al Mu'min      ራሱ፣ መጽሐፍቱና መልእክተኞቹ ስለርሱ የተናገሩትን የሚያጸድቅ 59:23
- #7 Al Muhaymin    በምሉእ ችሎታው ሁሉንም ነገር የሚቆጣጠር 59:23
- #8 Al Azeez       አቻ የለሽ ሐያልና አሸናፊ 3:6; 4:158; 9:40; 48:7
- #9 Al Jabbaar     ፈቃዱን በሐይል የሚፈጽም፣ ጠጋኝ እና ፈዋሽ 59:23
- #10 Al Mutakabbir የልዕልና ባህሪያቱ ብቸኛ ባለቤት፣ ከጉድለት የጸዳ 59:23
- #11 Al Khaaliq    ፍጡራንን በፈቃዱ ያስገኘ 6:102; 13:16; 39:62; 40:62; 59:24
