- #99 As Saboor     ጊዜ የሚሰጥ፣ የሚታገስ፣ የማይቸኩል 2:153; 3:200; 103:3
Matching Ayahs
- = አሊፍ፣ ላም፣ ሚም። 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = እነዚያ ከጌታቸው በመጣው ቅን መመሪያ ላይ ናቸው፤ እነሱም የተሳካላቸው ናቸው። 2:5; 31:5
- = የእስራኤል ልጆች ሆይ፤ በእናንተ ላይ ያደረግሁትን ጸጋዬን እና እኔ በዓለማት ላይ ማለትም በሕዝቦች ላይ ያልጠርሁትን አስታውሱ። 2:47; 2:122
- = ያች በእርግጥ ያለፈች ሕዝብ ናት። ለራሷ ያሳየችው አላት፤ ለእናንተም ያሳያችሁት አላችሁ። እነሱ ይሠሩት ስለነበረውም አትጠየቁም። 2:134; 2:141
- = በውስጧ ለዘለዓለም ቆዮች ሆነው፤ ቅጣቱ ከነሱ አይቀለልም፤ እነሱም እረፍት አይሰጡም። 2:162; 3:88
- = ከዚህ በኋላ ንስሐ ከገቡና ራሳቸውን ካስተካከሉ በስተቀር። አላህ በእርግጥ መሐሪ አዛኝ ነው። 3:89; 24:5
- = እነዚያ የካዱና በተኣምራቶቻችን ያስተበቱ እነሱ የገሀነም ባለቤቶች ናቸው። 5:10; 5:86
- = ከጌታቸው ተኣምራት አንዲቱም ተኣምር የምትመጣላቸው ከእርሷ ዘወር ካሉ በስተቀር አይደለም። 6:4; 36:46
- = ከአንተ በፊትም በእርግጥ መልክተኞች ተሳለቁባቸው፤ እነዚያም ያሾፉባቸውን (ቅጣት) በያዙት ነገር ተከበቡ። 6:10; 21:41
- = «እኔ ጌታዬን ብታዘዝ የታላቁን ቀን ቅጣት እፈራለሁ» በል። 6:15; 39:13
- = እርኩሰቱም ያዛቸው፤ በቤቶቻቸውም ውስጥ ተንጠልጥለው ሙታን ሆኑ። 7:78; 7:91
- = በትሩንም ጣለ፤ እነሆ እርሷ ግልጽ እባብ ሆነች። 7:107; 26:32
- = እጁንም አወጣ፤ እነሆ እርሷ ለተመልካቾች ነጭ (ብሩህ) ሆነች። 7:108; 26:33
- = «በዓለማት ጌታ አመንን» አሉ። 7:121; 26:47
- = የሙሳ እና የሃሩን ጌታ። 7:122; 26:48
- = ለእነሱም ጊዜ እሰጣቸዋለሁ፤ ማሰብየ በእርግጥ ጠንካራ ነው። 7:183; 68:45
- = እርሱ መልክተኛውን በቅን መሪነትና በእውነተኛ ሃይማኖት የላከው እነሱን (ሃይማኖቶችን) ሁሉ ለማሸነፍ ነው፤ ሙሽሪካውያን ቢጠሉም። 9:33; 61:9
- = ነቢዩ ሆይ፤ ከሓዲዎችንና ግብዞችን ተዋጋ፤ በእነሱም ላይ ጠንካራ ሁን፤ መኖሪያቸውም ገሀነም ናት፤ ምን ያስከፋ መመለሻ! 9:73; 66:9
- = «ይህ ተስፋ መቼ ነው? እውነተኞች እንደሆናችሁ» ይላሉ። 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = ሙሳንም በተኣምራቶቻችንና በግልጽ ማስረጃ በእርግጥ ላክነው። 11:96; 40:23
- = ሙሳንም መጽሐፍን በእርግጥ ሰጠነው፤ በእርሱ ግን ተለያዩበት። ከጌታህም የቀደመ ቃል ባይኖር ኖሮ በመካከላቸው በእርግጥ ይፈረድባቸው ነበር፤ እነሱም ከእርሱ በተጠራጣሪነት ውስጥ ናቸው። 11:110; 41:45
- = ይህ በአላህ ላይ ከባድ አይደለም። 14:20; 35:17
- = ባስተካከልሁትና ከፈጠርሁት መንፈስ በእርሱ ውስጥ በነፋሁት ጊዜ ለእርሱ ሰጂድ አድርጉ። 15:29; 38:72
- = መላእክቱም ሁሉ ሰገዱ። 15:30; 38:73
- = (አላህ) አለ፡ «ከእርሷ ውጣ፤ አንተ የተባረርክ ነህና።» 15:34; 38:77
- = (ኢብሊስ) አለ፡ «ጌታዬ ሆይ፤ እስከሚነሱበት ቀን ድረስ አቆየኝ።» 15:36; 38:79
- = (አላህ) አለ፡ «አንተም በእርግጥ ከተቆዩት ነህ።» 15:37; 38:80
- = እስከ ታወቀው ቀን ጊዜ ድረስ። 15:38; 38:81
- = ከነሱ የተመረጡት ባሮችህ በስተቀር። 15:40; 38:83
- = በእርግጥ ጥንቁቆቹ በአትክልቶችና በምንጮች ውስጥ ናቸው። 15:45; 51:15
- = (ኢብራሂም) አላቸው፡ «ታዲያ እናንተ መልክተኞች ሆይ፤ ጉዳያችሁ ምንድነው?» 15:57; 51:31
- = አሉ፡ «እኛ ወደ ኃጢአተኞች ሕዝብ ተልከናልና።» 15:58; 51:32
- = እነዚያ ያመኑና እምነታቸውን በበደል ያልቀላቀሉ እነሱ ደህንነት አላቸው፤ እነሱም ቅኑን መንገድ የተረገጡ ናቸው። 16:42; 29:59
- = (ይህንን የሚያደርጉት) በሰጠናቸው ነገር ሊክዱ ነው። ተደሰቱ፤ ወደፊትም ታውቃላችሁ። 16:55; 30:34
- = ከዚያም መንገድን ተከተለ። 18:89; 18:92
- = ወደ ፈርዖን ሂድ፤ እርሱ በእርግጥ ወሰን አልፏልና። 20:24; 79:17
- = እነዚያም የብልቶቻቸውን ጠባቂዎች ናቸው። 23:5; 70:29
- = ከሚስቶቻቸው ወይም ቀኝ እጆቻቸው ከያዙት (ባሮች) በስተቀር፤ እነሱ የማይወቀሱ ናቸውና። 23:6; 70:30
- = ከዚህ ባሻገር የሚፈልግ ማንኛውም ሰው እነዚያ ወሰን አላፊዎች ናቸው። 23:7; 70:31
- = እነዚያም ለአደራዎቻቸውና ለቃል ኪዳናቸው ጠባቂዎች ናቸው። 23:8; 70:32
- = (ኑህ) አለ፡ «ጌታዬ ሆይ፤ እነሱ ስላስተበቱኝ እርዳኝ።» 23:26; 23:39
- = ጣ፣ ሲን፣ ሚም። 26:1; 28:1
- = እነዚህ ግልጽ ከሆነው መጽሐፍ አንቀጾች ናቸው። 26:2; 28:2
- = በዚህ ውስጥ በእርግጥ ተኣምር አለ፤ አብዛኞቻቸውም አማኞች አልነበሩም። 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = ጌታህም በእርግጥ እርሱ አሸናፊው አዛኙ ነው። 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = ሌሎችንም አሳለፍን። 26:66; 37:82
- = እኔ ለእናንተ ታማኝ መልክተኛ ነኝ። 26:107; 26:125; 26:143; 26:162; 26:178
- = አላህንም ፍሩ፤ እኔንም ስሙኝ። 26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = በእርሱ ላይ ምንም ዋጋ አልጠይቃችሁም፤ ዋጌ በዓለማት ጌታ ላይ እንጂ አይደለም። 26:109; 26:127; 26:145; 26:164; 26:180
- = በአትክልቶችና በምንጮች ውስጥ። 26:147; 44:52
- = አሉ፡ «አንተ በእርግጥ ከተደነገሩት አንዱ ነህ።» 26:153; 26:185
- = ሚስቱ ብቻ ስትቀር – እሷ ከቀሩት መካከል እንድትሆን ወሰንን። 26:171; 37:135
- = ከዚያም ሌሎቹን አጠፋን። 26:172; 37:136
- = በእነሱም ላይ (የድንጋይ) ዝናብ አዘነብን፤ የተስፈራሩትንም ዝናብ ከፋ! 26:173; 27:58
- = ታዲያ ቅጣቱ እንዲቸኩል ነው? 26:204; 37:176
- = እነዚያ ሶላትን የሚያደርጉ፣ ዘካን የሚሰጡና እነሱ በመጨረሻይቱ ዓለም የሚያረጋግጡ ናቸው። 27:3; 31:4
- = ያንንም ቀን አስታውስ (አላህ) በጠራቸውና «እነዚያ (በአጋርነት) የተገመታችሁ ተጋሪዎቼ ወዴት ናቸው?» በሚልበት ጊዜ። 28:62; 28:74
- = አባቶቻችንስ? 37:17; 56:48
- = አንዳቸው ወደ አንዱም እየተጠያየቁ ይቀርባሉ። 37:27; 52:25
- = ግን (እነሱ) የአላህ ምርጥ ባሮች ናቸው። 37:40; 37:74; 37:128; 37:160
- = በመደሰቻ ገነቶች ውስጥ። 37:43; 56:12
- = ለእርሱም (ክብር) በኋለኞቹ ዘንድ ትውስታ አደረግን። 37:78; 37:108; 37:129
- = እኛ በእርግጥ በጎ አድራጊዎችን እንደዚሁ እንመስግናለን። 37:80; 37:121; 37:131; 77:44
- = እርሱ በእርግጥ ከምናምናቸው ባሮቻችን ነበር። 37:81; 37:111; 37:132
- = (እናንተን) ምን አጋጣማችሁ? እንዴት ትፈርዳላችሁ? 37:154; 68:36
- = እርሱ (ቁርአን) ለዓለማት ግሳጼ እንጂ ሌላ አይደለም። 38:87; 81:27
- = መጽሐፉ መውረድ ከአላህ አሸናፊው ጠቢቡ ነው። 39:1; 45:2; 46:2
- = ሀ፣ ሚም። 40:1; 41:1; 42:1; 43:1; 44:1; 45:1; 46:1
- = ግልጽ በሆነው መጽሐፍ እምላለሁ። 43:2; 44:2
- = የሚቀጣጠሩበትን ቀናቸውን እስከሚያገኙ ድረስ በከንቱ ውስጥ እንዲጫወቱና እንዲዝናኑ ተዋቸው። 43:83; 70:42
