- በእናንተ ላይ የከለከለው የሬሳ፣ ደም፣ የአሳማ ሥጋ እና ለሌላ (ለጣዖት) የታረደውን ብቻ ነው። (إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 16:115
- ከአላህ ሌላ እንዳትገዙ፣ እኔ በናንተ ላይ የታላቅ ቀንን ቅጣት እፈራለሁ። (أَن لَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ) 11:26; 46:21
- ይህ ከሩቅ ዜናዎች ነው፣ ወደ አንተ የምናወርደው፣ አንተም እነሱ ሲወስኑ ከእነሱ ጎን አልነበርክም። (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ) 3:44; 12:102
- ከጌታችሁ በእናንተ ውስጥ በሆነ ሰው ላይ ግሳጼ መጣላችሁ ትገረማላችሁ? (أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَى رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ) 7:63; 7:69
- በል፡- "እኔ ከአላህ ሌላ የምትጠሯቸውን እንዳላመልክ ተከልክያለሁ።" (قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ) 6:56; 40:66
- ከሚስቶቻቸው ወይም ቀኝ እጆቻቸው ከሚይዟቸው (ባሮች) በስተቀር፣ እነሱ የማይወቀሱ ናቸው። (إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ) 23:6; 70:30
- አላህ ሌሊትን በቀን ውስጥ ያስገባል እና ቀንንም በሌሊት ውስጥ ያስገባል። (بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ) 22:61; 31:29
- እሳት፣ ለቤተሰቦቹም አለ፡- "ቆዩ፣ እኔ እሳት አየሁ፣ ከእርሷ የሆነ ነገር ላመጣላችሁ እችላለሁ።" (نَارًا فَقَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا) 20:10; 28:29
- አለ፡- "እኔ ከእርሱ የበለጠ ነኝ፣ ከእሳት ፈጠርከኝ፣ እርሱንም ከጭቃ ፈጠርከው።" (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
- ለእነሱ ሲባል፡- "አላህ ያወረደው ወደሆነው እና ወደ መልእክተኛው ኑ።" (وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَى مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ) 4:61; 5:104
- በእነሱ ላይ አትዘን እና ከሚያደርጉት ተንኮል በጭንቀት ውስጥ አትሁን። (وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ) 16:127; 27:70
- አላህ በመከራ ቢነካህ፣ ከእርሱ ሌላ አስወጋጅ የለውም፣ እና በበጎ ቢነካህ። (وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن) 6:17; 10:107
- ከነሱ በፊት ያለፉ ትውልዶች፣ በመኖሪያ ቤቶቻቸው ውስጥ ይመላለሳሉ፣ በዚህ ውስጥ በእርግጥ ተዓምራት አሉ። (قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ) 20:128; 32:26
- በልቦቻቸው ላይ እንዳይገቡት መከለያዎችን አደረግን፣ በጆሮቻቸውም ውስጥ ክብደትን፣ እና ቢያዩትም። (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن) 6:25; 18:57
- መልእክተኞቻቸው በግልጽ ማስረጃዎች መጡላቸው፣ አላህ ሊበድላቸው አልነበረም ግን እነሱ ነፍሳቸውን ይበድሉ ነበር። (رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 30:9
- እና ምድርን፣ እና ከአላህ ሌላ ለናንተ ምንም ወዳጅ እና ረዳት የላችሁም። (وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 42:31
- ከዚያም ሩቅን እና ቅርብን ወደሚያውቀው (አላህ) ትመለሳላችሁ፣ ትሠሩት የነበራችሁትንም ይነግራችኋል። (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
- ሌሊትን በውስጡ ለማረፍ እና ቀንንም ለማየት፣ በዚህ ውስጥ ለሚያስቡ ሕዝቦች ተዓምራት አሉ። (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
- ከነሱ ብዙዎቹን ከጌታህ ወደ አንተ የተወረደው ነገር ትዕቢትን እና ክህደትን ይጨምርላቸዋል። (وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا) 5:64; 5:68
- አለ፡- "ወገኖቼ ሆይ! አያችሁት? እኔ ከጌታዬ በግልጽ ማስረጃ ላይ ብሆን እና እርሱ ቢሰጠኝ።" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي) 11:28; 11:63
- እነሱም ይላሉ፡- "በእርሱ ላይ ከጌታው ተዓምር አይወረድም?" በል፡- "ምንም አይደለም።" (وَيَقُولُونَ لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 29:50
- ከአላህ ዘንድ መመለስ ከሌለው ቀን በፊት። (مِن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا مَرَدَّ لَهُ مِنَ اللَّهِ) 30:43; 42:47
- ይህ የአላህ ችሮታ ነው፣ ለሚሻው ሰው ይሰጠዋል፣ አላህም የታላቅ ችሮታ ባለቤት ነው። (ذَلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 62:4
- በእንስሳት ውስጥ ለእናንተ ትምህርት አለ፣ በሆዳቸው ውስጥ ካለው ነገር እናጠጣችኋለን። (وَإِنَّ لَكُمْ فِي الْأَنْعَامِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِي بُطُونِهِ) 16:66; 23:21
- እርሱ ከጌታቸው የሆነ እውነት መሆኑን፣ አላህም ከሚሠሩት ነገር ዘንጊ አይደለም። (أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ وَمَا اللَّهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ) 2:144; 2:149
- ከፊታቸው እና ከኋላቸው፣ ከአላህ ሌላ እንዳትገዙ። (مِن بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوا إِلَّا اللَّهَ) 41:14; 46:21
- እናንተ ከሴቶች ሌላ በፍትወት ወደ ወንዶች ትመጣላችሁ፣ በእርግጥ እናንተ ወሰን አላፊ ሕዝቦች ናችሁ። (إِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِّن دُونِ النِّسَاءِ بَلْ أَنتُمْ قَوْمٌ) 7:81; 27:55
- ሰማያት እና ምድር እስካሉ ድረስ በውስጣቸው ዘላለም ተኑሪዎች ሲሆኑ፣ ጌታህ የሻው ካልሆነ በስተቀር። (خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ) 11:107; 11:108
- በሰማያት ውስጥ ያለው እና በምድር ውስጥ ያለው፣ አላህ የሻው ካልሆነ በስተቀር። (مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ إِلَّا مَن شَاءَ اللَّهُ) 27:87; 39:68
- በውስጣቸው ከወርቅ አምባሮች እና ከሉል ይጌጣሉ፣ ልብሳቸውም በውስጣቸው ሐር ነው። (يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ) 22:23; 35:33
- ከሰማይ ውሃ አወረደ፣ በእርሱም ከፍራፍሬዎች ለናንተ ምግብ አወጣ። (وَأنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِ مِنَ الثَّمَرَاتِ رِزْقًا لَّكُمْ) 2:22; 14:32
- የእናንተን ቃል ኪዳን በወሰድን ጊዜ እና ጡርን በላያችሁ ከፍ አደረግን፡- "የሰጠናችሁን በጥንካሬ ያዙ።" (وَإِذْ أَخَذْنَا مِيثَاقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَ خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ) 2:63; 2:93
