- እነዚያ ሶላትን የሚያስተካክሉ እና ዘካትን የሚሰጡ እና እነሱ በመጨረሻይቱ ዓለም የሚያምኑ ናቸው። (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- ኢብራሂምን፣ እስማኢልን፣ እስሐቅን፣ ያዕቆብን እና ነገዶችን፣ ሙሳ እና ዒሳ የተሰጡትንም። (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- ቡድን ቡድን ሆነው በመጡ ጊዜ በሮቿ ተከፍተውላቸው ጠባቂዎቿም ለእነሱ አሉ። (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- አላህ በመሐላዎቻችሁ በውሸት አይይዛችሁም፣ ግን በዚያ ይይዛችኋል። (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- ቸርነት፣ በእርሷ ደስ ይላቸዋል፣ መከራም በእጆቻቸው ባስቀደሙት ነገር ብትደርስባቸው። (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- ከሥሮቻቸው ወንዞች ይፈሳሉ፣ በውስጣቸው ዘላለም ተኑሪዎች ሲሆኑ፣ የሠራተኞችም ዋጋ ምን ያህል አማር ነው! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- አላህ በሰማያት ውስጥ ያለውን እና በምድር ውስጥ ያለውን ያውቃል፣ አላህም። (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- አላህን ታዘዙ እና መልእክተኛውን ታዘዙ፣ ብትዞሩም በእርሱ ላይ ብቻ ነው። (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- ለእነሱ በጌታቸው ዘንድ የራሳቸው ዋጋ አላቸው፣ በእነሱ ላይ ፍርሃት የለባቸውም እና እነሱም። (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- አሉም፡- "አጥንቶች እና ፍርስራሾች በሆንን ጊዜ እኛ አዲስ ፍጥረት እንደምንሆን?" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- ከአላህ ሌላ ለራሳቸው ምንም ወዳጅ እና ረዳት አያገኙም። (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- "ምን ያህል ቆየህ?" አለ፡- "አንድ ቀን ወይም የቀን ክፍል ቆየሁ።" አለ። (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- እስከ ትንሳኤ ቀን ድረስ ዘላለም፣ ከአላህ ሌላ የሚያመጣላችሁ አምላክ ማን ነው? (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- መልካም ሥራ የሠራ ሰው ከወንድ ወይም ከሴት፣ እርሱም አማኝ ሆኖ። (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- እነዚያ ከአላህ መንገድ የሚያግዱ እና ጥምጥም የሚፈልጉላት፣ እነሱም በመጨረሻይቱ ዓለም። (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- በሻችሁት ስፍራ (ተመገቡ) ነገር ግን ወደዚህች ዛፍ አትቅረቡ፣ ከበደለኞች ትሆናላችሁና። (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- በል፡- "ወገኖቼ ሆይ! በቦታችሁ ላይ ሥሩ፣ እኔም ሠራተኛ ነኝ፣ ወደፊትም ታውቃላችሁ።" (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- በእርግጥ ከሳሪዎቹ እነዚያ ነፍሶቻቸውን እና ቤተሰቦቻቸውን በትንሳኤ ቀን ያጡ ናቸው፣ አይደል? (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- ለራሱ ይምራል፣ የተሳሳተ ሰውም የሚሳሳተው ለራሱ ነው፣ እናም። (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- እነዚያ ያልመኑት ይላሉ፡- "በእርሱ ላይ ከጌታው ተዓምር አይወረድም?" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- ያ ለእናንተ ሌሊትን በውስጡ ለማረፍ እና ቀንንም ለማየት ያደረገላችሁ፣ በእርግጥ። (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- በውስጡ ምንም ግብይት እና ወዳጅነት ከሌለበት ቀን በፊት። (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- በጓደኛቸው ላይ ምንም ዓይነት እብደት እንደሌለ ያስተውሉ፣ እርሱ ግልጽ አስጠንቃቂ እንጂ ሌላ አይደለም። (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- በውስጧ ዘላለም ተኑሪዎች ሲሆኑ፣ ቅጣቱ ከእነሱ አይቀለልላቸውም እንዲሁም አይቆዩም። (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- ዓይኖችህን በውስጡ ጥቂቶቻቸውን ባስደሰትንበት ነገር ላይ አትዘርጋ። (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- ሰዎችን ንብረቶቻቸውን አትቀንሱ እና በምድር ላይ አጥፊዎች ሆናችሁ አትበድሉ። (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- በእርሱ ላይ ሰላም ይሁን በተወለደበት ቀን፣ በሚሞትበት ቀን እና በሚነሳበት ቀን በሕይወት ሆኖ። (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- ወገኖቼ ሆይ! በቦታችሁ ላይ ሥሩ፣ እኔም ሠራተኛ ነኝ፣ ወደፊትም ማን እንደሆነ ታውቃላችሁ። (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- ለማንኛውም መልእክተኛ በአላህ ፈቃድ ካልሆነ በስተቀር ተዓምር ሊያመጣ አይቻለውም። (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- ከዚያም እያንዳንዷ ነፍስ ያስገኘችውን (ዋጋ) ትሞላለች፣ እነሱም አይበደሉም። (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- ከወንድ ወይም ከሴት፣ እርሱም አማኝ ሆኖ፣ እነዚያ ገነትን ይገባሉ። (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- ልጅ አልወሰደም እና በንጉሥነቱ ውስጥ ለእርሱ ተጋሪ አልነበረም። (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- አላህ ያስተካከለው ሰው እርሱ ቀጥተኛ ነው፣ ያሳሳተውንም ለእርሱ መሪ አታገኝም። (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
