- አላህ በሰማያትና በምድር ያለውን ያውቃል። (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 3:29; 5:97; 49:16; 58:7
- ከሥራቸው ወንዞች የሚፈሱ ገነቶች, በውስጧ ዘላለማዊ ኾነው, ያ ደግሞ። (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ) 4:13; 5:85; 9:89; 57:12
- ዋጋው በጌታው ዘንድ ነው, በእነርሱም ላይ ፍርሃት የለባቸውም, እነርሱም። (أَجْرُهُ عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:112; 2:262; 2:274; 2:277
- በጌታው ዘንድ, በእነርሱም ላይ ፍርሃት የለባቸውም, እነርሱም አያዝኑም። (عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ) 2:112; 2:262; 2:274; 2:277
- ቀጥታ ያገኘ ሰው, የሚገኘው ለራሱ ነው, የጠፋም። (فَمَنِ اهْتَدَى فَإِنَّمَا يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ) 10:108; 17:15; 27:92
- ለራሱ ይገኛል, የጠፋም ሰው, የሚጠፋው በራሱ ላይ ነው። (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا) 10:108; 17:15; 39:41
- በርሱ ላይ ከጌታው ተአምር አይወረድም ነበርን? በል: እውነቱ። (لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 13:27; 29:50
- እነዚያ ያመኑና መልካም ሥራዎችን የሠሩ, ለእነርሱ የማይቋረጥ ዋጋ አላቸው። (الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 41:8; 84:25; 95:6
- ሕያውን ከሙት ታወጣለህ, ሙትንም ከሕያው ታወጣለህ። (وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ) 3:27; 10:31; 30:19
- አላህ ባወረደው የማይፈርድ ሰው, እነዚያ እነርሱ ናቸው። (وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَئِكَ هُمُ) 5:44; 5:45; 5:47
- ሰማያትንና ምድርን እንዲሁም በመካከላቸው ያለውን በስድስት ቀናት ፈጠረ። (خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ) 25:59; 32:4; 50:38
- አላህ በሰዎች ላይ ችሮታ ባለቤት ነው, ግን አብዛኞቹ። (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ) 2:243; 10:60; 40:61
- አላህ እነርሱን የሚበድል አልነበረም, ግን እነርሱ ነፍሳቸውን ይበድሉ ነበር። (فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 29:40; 30:9
- ኃጢአቶቻችሁን ይሸፍንላችኋልና ከሥራቸው ወንዞች የሚፈሱ ገነቶች ያስገባችኋል። (عَنكُمْ سَيِّئَاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 5:12; 64:9; 66:8
- በላያችሁ የከለከላችሁ የሞተችውን, ደምን, የአሳማን ሥጋና በርሱ የተሰየደውን። (حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 5:3; 16:115
- እኔ ጌታዬን ባላስተዋልሁ, የታላቅ ቀንን ቅጣት እፈራለሁ። (إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 10:15; 39:13
- ዕውቀት ከመጣላቸው በኋላ ብቻ, በመካከላቸው በጥላቻ። (إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ) 3:19; 42:14; 45:17
- ሶላትንም ተማሩ, ከሰጠናቸውም ስውርና ግልጽ ሆነው ለገሱ። (وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً) 13:22; 14:31; 35:29
- ከአላህ ሌላ, የማይጠቅመንና የማይጎዳን (አምላክ)። (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- ወደ አንተ በተወረደውና ካንተ በፊት በተወረደው ያምናሉ። (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- አላህ ከሰማይ ውሃ እንዳወረደ አላየህምን? (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- አንድን ነገር በፈቀደ ጊዜ, ለርሱ ይለዋል: ኩን (ሁን), ወዲያውም ይኾናል። (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- ወደ መድየንም ወንድማቸውን ሹአይብን (ላክን), አለ: ወገኖቼ ሆይ, አላህን ተገዙ። (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- ይህ ከሩቅ ዜናዎች ነው, ወደ አንተ እናወርደዋለን, አንተም። (ذَلِكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- ጊዜያቸው በመጣ ጊዜ, አንድ ሰዓት አይዘገዩም, አይቀድሙምም። (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- የሰይጣንን ፈለግ አትከተሉ, እርሱ ለእናንተ ግልጽ ጠላት ነውና። (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- ከሰዎችም ያለ ዕውቀት በአላህ የሚከራከር ሰው አለ። (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- አላህ ለሚሻው ሰው ይሰጣል, አላህም የታላቅ ችሮታ ባለቤት ነው። (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- ነፍስ ሁሉ የሠራችውን ትቀበላለች, እነርሱም አይበደሉም። (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- አላህ ያረገውን ነፍስ በደል ሳይኾን አትግደሉ። (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- አንድን ነገር በፈቀደ ጊዜ, ለርሱ ይለዋል: ኩን (ሁን)። (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- የገሀነምን በሮች ግቡ, በውስጧ ዘላለማዊ ኾነው; የትዕቢተኞች መኖሪያ ከፋ ሆነች! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- ከመጽሐፉ ድርሻ የተሰጡትን አላየህምን? (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- ለእነርሱ ከሥራቸው ወንዞች የሚፈሱ ገነቶች አሏቸው, በውስጧ ዘላለማዊ ኾነው። (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- ወገኖቼ ሆይ, በቦታችሁ ላይ ሥሩ, እኔም ሠራተኛ ነኝ, ወደፊት ታውቃላችሁ። (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- አላህንና መልክተኛውን (የሚቃወም), ለርሱ የገሀነም እሳት አለበት, በውስጧ ዘላለማዊ ኾኖ። (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- በልቦቻቸው ላይ መከለያዎችን, እንዳያስተውሉት, በጆሮዎቻቸውም ውስጥ መስማት መቆረጥን (አደረግን)። (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- በአንዲት መንደር አስጠንቃቂ ቢመጣ, ባለጸጎቿ እንደሚሉ በቀር: እኛ። (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- አሉ: ምን እንደኾነች ሊያብራራልን ጌታህን ጥራልን። (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- አላህ ነው ይላሉ። በል: ምስጋና ለአላህ ይገባዋል, ግን አብዛኞቻቸው። (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- የሕዝቦቹም መልስ: አውጧቸው ማለታቸው በቀር አልነበረም። (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- ከሥራቸው ወንዞች የሚፈሱ, በውስጧ ለዘላለም ኾነው, ያ ታላቅ ምሩቅ ነው። (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- እነዚያ ከጌታቸው በመገኛ ላይ ናቸው, እነርሱም የተሳካላቸው ናቸው። (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- የሚያዋርደው ቅጣት የሚመጣበትና የማይወገድ ቅጣት የሚወርድበት ሰው። (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- በምድር ላይ ሂዱና የአስተባባዮች መጨረሻ እንዴት እንደነበረ ተመልከቱ። (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- እጆቻቸው ባስቀደሙት ምክንያት መቼም አይመኙትም, አላህም በደለኞችን ዐዋቂ ነው። (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- እርሱ ከመንገዱ የጠፋውን በሚገባ ያውቃል, እርሱም በሚገባ ያውቃል። (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- አላህ ጌታዬ እና ጌታችሁ ነው, ስለዚህ ተገዙት, ይህ ቀጥተኛ መንገድ ነው። (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- በሰዎች ላይ ችሮታ ባለቤት ነው, ግን አብዛኞቻቸው አያመሰግኑም። (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- ሰማያትንና ምድርን እንዲሁም በመካከላቸው ያለውን በእውነትና በተወሰነ ጊዜ ብቻ (ፈጠርነው)። (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- ተዋቸው በከንቱ ይዝለሉ እና ይጫወቱ, የሚቀጣጠበትን ቀናቸውን እስኪያገኙ ድረስ። (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- እነዚያን ያመኑትን ሲያገኙ: አምነናል ይላሉ, ብቻቸውንም ሲቀሩ። (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- ተውራትንና ኢንጂልን እንዲሁም ከጌታቸው ወደነርሱ የተወረደውን ያስተካክላሉ። (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- በፊታቸው ያለውንና ከበስታቸው ያለውን ያውቃል, እነርሱም አያካብቡትም። (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- እርሱም ያ ሰማያትንና ምድርን በስድስት ቀናት ውስጥ የፈጠረው ነው። (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- በዚህ ውስጥ አማኞች እንደ ኾናችሁ ለናንተ ተአምር አለ። (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- ሰዎችን መመሪያ በመጣላቸው ጊዜ ከማመን የከለከላቸውም። (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- ለአላህም ከመንገዱ ሊያሳስቱ ተካካዎችን አደረጉ። በል: ተደሰቱ። (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- ከነርሱ መካከል አስጠንቃቂ መጣላቸውን ተገረሙ, ከሓዲዎቹም አሉ: ይህ። (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- ጌታህ እርሱ ከመንገዱ የጠፋውን በሚገባ ዐዋቂ ነው። (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- ልክ ገንዘቡን ለሰዎች ማሳያ እንደሚያወጣ, በአላህም የማያምን ሰው። (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- ከሰጠናችሁ ሲሳይ ከመምጣቱ በፊት ለግሱ። (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- በሰማያትና በምድር ያለውን ሁሉ ለእናንተ ገዛ። (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- እኛም ወደርሱ በምትጠሩን ነገር በአጠያያቂ ጥርጣሬ ውስጥ ነን። (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- ጌታህ ሲሳይን ለሚሻው ሰው ያሰፋል, ያጠብምም, እርሱ። (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- የሰማያትና የምድር ጌታ እንዲሁም በመካከላቸው ያለው, የምታረጋግጡ ከ ኾናችሁ። (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- በአላህና ወደእኛ በተወረደውና ወደ. (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- በደለኞቹንም ጩኸት ያዘቻቸው, በመኖሪያቸውም ውስጥ ተንበርካኪ ኾነው አነጉ። (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- በራሳቸው ባደረጉት ነገር በእናንተ ላይ ኀጢአት የለባችሁም። (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- ጌታህ እርሱ ከመንገዱ የጠፋውን በሚገባ ያውቃል, እርሱም። (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- ከትእዛዙ ወደሚሻው ባሪያው በመንፈስ (በራዕይ)። (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- ለመርየም ልጅ ኢሳንም ግልጽ ማስረጃዎችን ሰጠነው, በቅዱስ መንፈስም አጠናከርነው። (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- በትንሳኤ ቀን በመካከላቸው በሚለያዩበት ነገር ይፈርድባቸዋል። (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- የላይኛዋን የታችኛዋ አደረግን, በላዩም የሸክላ ጠጠር አዘነብንባት። (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- በእነርሱ ላይ ብታስጠንቅቅም ባታስጠንቅቅም እኩል ነው, አያምኑም። (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- ከሰዎች ሌላ, እውነተኞች ከ ኾናችሁ ሞትን ተመኙ። (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- አላህን, ከርሱ ሌላ አምላክ የላችሁም። አትፈሩምን? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- የምንቀጣጠበውን አንዳንዱን ብናሳይህም, ወይም ብንገድልህም, ወደእኛ መመለስ ነው። (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- አሉ: በሞትንና አፈርና አጥንት በ ኾንን ጊዜ, በእውነት እኛ ተነሳሾች ነን? (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- ችሮታ በአላህ እጅ ነው, ለሚሻው ሰው ይሰጣል, አላህም። (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- ሩቅና ቅርብ ወደሚያውቀው (አላህ) ትመለሳላችሁ, ትሠሩት የነበራችሁትንም ይነግራችኋል። (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- እናንተ ያመናችሁ ሆይ, አላህን ጸጋ በላያችሁ ላይ አስታውሱ, በጊዜ. (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- ካንተ በፊትም ወደነርሱ የምናወርድላቸው ወንዶችን በቀር አልላክንም። (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- ኃጢአቶቹን ያስወግድለታልና ከሥራቸው ወንዞች የሚፈሱ ገነቶች ያስገባዋል። (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- በሕመም ወይም በጉዞ ላይ ከ ኾነ, ከሌሎች ቀናት ቁጥር (ይጾም)። (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- ጥርጣሬን በቀር አይከተሉም, እነርሱም የሚገምቱ ብቻ ናቸው። (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- አላህንና የመጨረሻውን ቀን ለሚፈራ መልካም አርአያ ነው። (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- ሰማያትንና ምድርን እንዲሁም በመካከላቸው ያለውን በእውነት ብቻ አልፈጠርንም። (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- እጅህን ወደ ኪስህ ግባ, ያለ ጉዳት ነጭ ኾና ትወጣለች። (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- በቸርነቱ የሚሻውን ይመርጣል, አላህም የታላቅ ችሮታ ባለቤት ነው። (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- አላህ የሰማያትና የምድር ንጉሥ መኾኑን አላወቅህምን? (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- ከበጎ ሥራ ለነፍሳችሁ ያስቀደማችሁት, በአላህ ዘንድ ታገኙታላችሁ። (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- ከወጣህበትም ስፍራ ሁሉ ፊትህን ወደ ቅዱስ መስጊድ አዙር። (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- ከበፊታቸው ያለፉት (እንደሆኑ), ለአላህ ሕግም መቀየር አታገኝም። (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- ያ በሰማያትና በምድር ያለው ሁሉ የርሱ ለኾነው። (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- ሴትም አትጸንስም, አትወልድም, በእውቀቱ ብቻ ካልኾነ በቀር። (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- ሌሊትን, ፀሐይንና ጨረቃንም ገዛ, ሁሉም ለተወሰነ ጊዜ ይሮጣሉ። (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- ከሥራቸው ወንዞች የሚፈሱ, በውስጧ ዘላለማዊ ኾነው, ያም የዋጋ ነው። (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- አለ: አይደለም, ነፍሶቻችሁ አንድን ነገር ለእናንተ አስመለከቱ; መልካም ትዕግሥት (ያስፈልጋል)። (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- በሰማያትና በምድር ያለው, እንዲሁም አላህ። (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- ከመልክተኞች የሚመጣቸውም ማንኛውም መልክተኛ, ያሾፉበት ቢኾኑ በቀር። (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- አሉ: ሙሳ ሆይ, ወይ አንተ ትጥላለህ, ወይም እኛ እንኾን (እንጥላለን)። (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- እርሱ ያሞታችኋል, ከእናንተም አንዳንዱ ወደ በጣም የከፋ ዕድሜ ይመለሳል, (ከዕውቀት በኋላ). (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- ለእነርሱ ከጌታቸው ዘንድ ከሥራቸው ወንዞች የሚፈሱ ገነቶች አሏቸው, በውስጧ ዘላለማዊ ኾነው። (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- በልቦቻቸው ላይ መከለያዎችን, እንዳያስተውሉት, በጆሮዎቻቸውም ውስጥ መስማት መቆረጥን (አደረግን)። (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- የአላህ ቃል ኪዳን እውነት ነው, ግን አብዛኞቻቸው አያውቁም። (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- ይህ, እነርሱ አላህንና መልክተኛውን ስለተቃወሙ ነው; አላህንም የሚቃወም ሰው። (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- በሚጠራቸውም ቀን: ትጠሩ የነበራችሁ ተጋሮቼ ወዴት ናቸው? (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- ያ ሰማያትንና ምድርን የፈጠረው አላህ መኾኑን አላዩምን? (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- በዚያ ከአፈር, ከዚያም ከፍተ ዘር, ከዚያም። (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- ይላሉ: ጌታችን ሆይ, ወደእኛ መልክተኛ ባወረድክ ኖሮ ተአምሮችህን እንከተል ነበር። (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- ከዚያም መመለሻቸው ወደ ጌታቸው ነው, ይሠሩት የነበሩትንም ይነግራቸዋል። (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- ለእነርሱ በዚህ ምንም ዕውቀት የላቸውም, እነርሱ ግምትን ብቻ ይከተላሉ። (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- እኛ አባቶቻችንን በአንድ ሃይማኖት ላይ አገኘን, እኛም በፈለጋቸው ላይ ነን። (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- እነዚያ መጽሐፍ የተሰጡት, ከመጣላቸው በኋላ ብቻ ካልኾነ በቀር። (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- ኢብራሂምም ባለ ጊዜ: ጌታዬ ሆይ, ይህችን አገር ደህንኛ አድርጋት። (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- መስሚያን, ማየትንና ልቦችንም ለእናንተ አደረገ; ጥቂት ትመሰግናላችሁ። (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- እነዚያ በአላህ ተአምራት ያለ መጣላቸው ሥልጣን የሚከራከሩ። (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- የኢብራሂምን ሃይማኖት ቀጥተኛ ኾኖ ተከተሉ, ከአረብ አማልክተኞችም አልነበረም። (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- ከፈርዖን ቤተሰቦችም አዳንናችሁ, ክፉውን ቅጣት ያቀምሱአችሁ ነበርና። (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- ይህች ትክክለኛዋ ሃይማኖት ናት, ግን አብዛኞቹ ሰዎች አያውቁም። (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- አላህ በሰማያት ያለውን ለእናንተ ያስገዛላችሁ መኾኑን አላየህምን? (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- እነዚያ ያልመኑት: ይህ ግልጽ ድግምት እንጂ ሌላ አይደለም ይላሉ። (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- በእነርሱ ላይ ተአምራቶቻችን ግልጽ ሆነው በሚነበቡበት ጊዜ, እነዚያ ያልመኑት ይላሉ። (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- የመኖሪያ ገነቶች, ከሥራቸው ወንዞች የሚፈሱ, በውስጧ ዘላለማዊ ኾነው። (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- የሚሸውን, አላህ በሁሉ ነገር ላይ ቻይ ነው። (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- ኃጢአቶቻችሁን ይምርላችኋልና ወደ ተወሰነ ጊዜ ያራዝማችኋል። (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- አባቶቻችን ያመልኩት ከነበረው ልትከለክሉን ትፈልጋላችሁን? (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- ጌታህም ለመላእክት ባለ ጊዜ: እኔ ሰውን ከ. ፈጣሪ ነኝ። (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- እርሱም ያ በቸርነቱ ፊት ምሥራችን ነፋሶችን የሚልክ ነው። (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- በል: በምድር ላይ ሂዱና መጨረሻው እንዴት እንደነበረ ተመልከቱ። (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- ሰማያትንና ምድርን በመፍጠር እንዲሁም ሌሊትና ቀንን በመቀያየር ውስጥ (ተአምራት አሉ)። (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- ያ አላህን መልካም ብድር የሚያበድረው ማን ነው? ለርሱ ያበዛለታል። (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- አላህ ባወረደው በመካከላቸው ፍረድ, ፍላጎቶቻቸውንም አትከተል። (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- መላእክት ሊመጡላቸው ወይም (የጌታህ) ትዕዛዝ ሊመጣ በቀር ሌላ ይጠብቃሉን? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- እነዚያ በአላህ ላይ ውሸት የሚቀጣጥፉ, አይታደጉም። (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- ልክ እንደ ፈርዖን ቤተሰቦችና ከበፊታቸው የነበሩት ልማድ, ተአምራቶቻችንን አስተባበሉ። (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- እነዚያን መልካም ሥራዎችን የሚሠሩ አማኞችን ለእነርሱ መልካም ምንዳ እንዳላቸው ያስደስታል። (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- አላህ ሲሳይን ለሚሻው ባሪያው ያሰፋል, ያጠብምም። (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- ወደ ሩቅና ቅርብ ወደሚያውቀውም ትመለሳላችሁ, ትሠሩት የነበራችሁትንም ይነግራችኋል። (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- የዝምድና ባለቤቶችም አንዳንዶቻቸው በአላህ መጽሐፍ ውስጥ ከሌሎች ይልቅ ቅርብ ናቸው። (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
""";
